import json
def production_page(project_id,completed=False):
    return HTML.replace('__PAYLOAD__',json.dumps(dict(project_id=project_id,completed=completed)).replace('<','\\u003c'))
HTML=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arquivos do circuito</title><style>
body{margin:0;background:#f6f8f5;color:#203b37;font:15px/1.6 "Segoe UI",Arial}main{max-width:1050px;margin:auto;padding:20px}section{background:white;border:1px solid #dce5e0;border-radius:14px;padding:24px;margin:16px 0}h2{margin:0 0 8px}p{color:#647772}.bar,.downloads{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}button,.button{font:600 14px "Segoe UI",Arial;border:1px solid #cadbd2;border-radius:9px;background:#16735d;color:white;padding:12px 16px;cursor:pointer;text-decoration:none}input,select{font:inherit;border:1px solid #cadbd2;border-radius:8px;padding:10px;max-width:100%;box-sizing:border-box}input[type=url]{width:100%}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #e5ece8}.status{background:#edf5f0;padding:12px 16px;border-radius:10px}#qr{width:220px;max-width:100%}.share-layout{display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center}#linkText{overflow-wrap:anywhere}[hidden]{display:none!important}button:disabled{opacity:.45}summary{cursor:pointer}@media(max-width:650px){main{padding:12px}section{padding:18px}.share-layout{grid-template-columns:1fr}table,tbody,tr,td{display:block}thead{display:none}}
</style></head><body><main><div id="status" class="status" role="status">Carregando seus arquivos…</div>
<section id="setup"><h2>Arquivos para baixar</h2><p>O esquemático conectado, o circuito Falstad e o projeto completo serão gerados ao continuar.</p><label><input id="pcb" type="checkbox"> Incluir PCB com roteamento inicial</label><div id="physical" hidden><p>Escolha o encapsulamento de cada componente. Conectores representam os sinais quando o encapsulamento ainda não foi definido.</p><table><thead><tr><th>Componente</th><th>Pinos</th><th>Encapsulamento</th></tr></thead><tbody id="components"></tbody></table><p>Confira encapsulamentos e alimentação do amplificador antes de fabricar. O roteamento conecta os pads disponíveis e informa o que faltar.</p></div><div class="bar"><button id="generate">Gerar esquemático e PCB</button><button id="reload">Atualizar arquivos</button></div><h2>Abrir no celular</h2><p id="networkMessage">Use a mesma rede Wi-Fi do computador e mantenha o programa aberto.</p><label>Endereço do computador na rede<input id="address" type="url" aria-label="Endereço do servidor"></label><small>O QR Code usará este endereço. Ajuste se houver mais de uma rede.</small><div class="bar"><button id="export">Gerar ZIP e QR Code</button></div></section>
<section id="shared" hidden><h2>Seu projeto está pronto</h2><p>Escolha um arquivo ou abra a simulação pelo celular.</p><div class="downloads"><a id="zip" class="button">Projeto completo · ZIP</a><a id="schematic" class="button">Esquemático · KiCad</a><a id="board" class="button" hidden>PCB · KiCad</a><a id="falstadDownload" class="button">Circuito · Falstad</a></div><div class="share-layout"><div><h2>Abrir no celular</h2><p id="phoneMessage">Conecte o celular ao mesmo Wi-Fi e escaneie o QR Code.</p><a id="link" target="_blank" rel="noopener">Abrir circuito compartilhado</a><p id="linkText"></p><button id="revoke">Desativar link</button></div><img id="qr" alt="QR Code para abrir o circuito no celular"></div></section>
</main><script id="payload" type="application/json">__PAYLOAD__</script><script>
const cfg=JSON.parse(document.getElementById('payload').textContent),base='/projects/'+encodeURIComponent(cfg.project_id),el=id=>document.getElementById(id);let rev=null,data=null,busy=false;
function message(text){el('status').textContent=text}
async function request(url,options){const r=await fetch(url,options),d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Não foi possível concluir.');return d}
function post(url,payload){return request(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}
function controls(){el('generate').disabled=busy||!data?.confirmed;el('export').disabled=busy||!data?.kicad;el('revoke').disabled=busy||!data?.share_enabled}
function rows(){el('components').replaceChildren();for(const c of data.components||[]){const tr=document.createElement('tr');for(const text of [c.id,c.pins.join(', ')]){const td=document.createElement('td');td.textContent=text;tr.append(td)}const td=document.createElement('td'),select=document.createElement('select');select.dataset.component=c.id;select.setAttribute('aria-label','Encapsulamento de '+c.id);for(const [key,p] of Object.entries(data.presets)){if(p.count!==c.pins.length||(p.types&&!p.types.includes(c.type)))continue;const o=document.createElement('option');o.value=key;o.textContent=p.label;select.append(o)}select.value=data.kicad?.options.footprints[c.id]||'terminal_'+c.pins.length;td.append(select);tr.append(td);el('components').append(tr)}}
async function load(){data=await request(base+'/production');rev=data.revision;rows();el('pcb').checked=data.kicad?!!data.kicad.pcb:true;el('physical').hidden=!el('pcb').checked;el('setup').hidden=cfg.completed;el('shared').hidden=!data.export||!data.share_enabled;el('schematic').href=base+'/kicad/download/schematic';el('board').href=base+'/kicad/download/pcb';el('board').hidden=!data.kicad?.pcb;el('falstadDownload').href=base+'/circuitjs/download';if(data.export){el('zip').href=base+'/export/download';el('link').href=data.export.share_url;el('linkText').textContent=data.export.share_url;el('qr').src=base+'/export/qr?v='+Date.now();el('phoneMessage').textContent=data.export.local_address?'O endereço ainda é local. Gere o QR com o IP do computador para abrir no celular.':'Conecte o celular ao mesmo Wi-Fi e escaneie o QR Code.'}message(cfg.completed?'Seus arquivos estão prontos.':!data.confirmed?'Confirme o circuito para continuar.':'Escolha os arquivos e continue para gerar seu projeto.');controls()}
async function run(fn){busy=true;controls();try{await fn()}catch(e){message(e.message)}finally{busy=false;controls()}}
el('pcb').onchange=()=>el('physical').hidden=!el('pcb').checked;el('reload').onclick=()=>run(load);
el('generate').onclick=()=>run(async()=>{const footprints={};for(const s of document.querySelectorAll('select[data-component]'))footprints[s.dataset.component]=s.value;await post(base+'/kicad',{base_revision:rev,pcb:el('pcb').checked,footprints});await load()});
el('export').onclick=()=>run(async()=>{await post(base+'/export',{base_revision:rev,base_url:el('address').value});await load()});
el('revoke').onclick=()=>run(async()=>{await post(base+'/share/revoke',{});await load();message('Link desativado. Seus arquivos continuam salvos.');parent.postMessage({type:'guided-refresh',phase:'done'},location.origin)});
window.GuidedReady=Promise.all([load(),request('/sharing/address').then(d=>{el('address').value=d.address;el('networkMessage').textContent=d.message})]).then(()=>{if(data.circuit_absent)message('Este projeto ainda não tem arquivos. Volte ao reconhecimento pela navegação para concluir o circuito.');return true}).catch(e=>{message(e.message);return false});
</script></body></html>'''
